import { isTargetLanguage, type TargetLanguage } from './types';

/**
 * Format of the translation glossary note (default `Translation glossary.md`).
 * Like the cache it is a visible note (warning line plus JSON, one entry per
 * line), so it syncs, can be reviewed and is easy to diff. Unlike the cache it
 * holds what the user taught the plugin, so it lives outside the cache folder
 * and "Clear cache" never touches it.
 */

export const GLOSSARY_VERSION = 1;

export const GLOSSARY_WARNING =
	'Generated by the Transparent Translate plugin. This is your translation glossary: change it in the plugin (Manage translation glossary), or carefully by hand.';

/** `map`: translate this term as `to`. `avoid`: never use these translations. `keep`: do not translate. */
export type GlossaryKind = 'map' | 'avoid' | 'keep';

/**
 * Where an entry applies. Exactly one field is set; an empty object means the
 * whole vault. Most specific wins: note, then property or tag, then the
 * deepest folder, then the vault.
 */
export interface GlossaryScope {
	folder?: string;
	note?: string;
	/** Frontmatter property, e.g. `course` = `SYS`. */
	property?: { key: string; value: string };
	tag?: string;
}

export interface GlossaryEntry {
	kind: GlossaryKind;
	/** Term in the source text, as the user would write it. */
	src: string;
	/** Language this applies to, `*` for both. */
	target: TargetLanguage | '*';
	/** Preferred translation (`map`). */
	to?: string;
	/** Translations that are wrong (`avoid`). */
	avoid?: string[];
	scope: GlossaryScope;
	/** Short note on the sense of the term, sent to the model. */
	hint?: string;
	/** `stem` also matches compounds and inflections (default for terms of 4+ letters); `word` only the whole word. */
	match?: 'stem' | 'word';
	updatedAt: string;
	/** Tombstone: kept for a while so a sync cannot bring a deleted entry back. */
	deleted?: true;
}

export interface GlossaryDomain {
	text: string;
	updatedAt: string;
}

export interface GlossaryFile {
	version: number;
	entries: Record<string, GlossaryEntry>;
	/** Short description of the subject area per scope key (see `scopeKey`). */
	domains: Record<string, GlossaryDomain>;
}

export const MAX_SRC = 60;
export const MAX_TO = 80;
export const MAX_HINT = 120;
export const MAX_DOMAIN = 300;
const TOMBSTONE_DAYS = 90;

export function emptyGlossary(): GlossaryFile {
	return { version: GLOSSARY_VERSION, entries: {}, domains: {} };
}

/** Stable text form of a scope, used as map key and for display. */
export function scopeKey(scope: GlossaryScope): string {
	if (scope.note) return `note:${scope.note}`;
	if (scope.property) return `property:${scope.property.key}=${scope.property.value}`;
	if (scope.tag) return `tag:${scope.tag.replace(/^#/, '')}`;
	if (scope.folder) return `folder:${scope.folder.replace(/\/+$/, '')}`;
	return 'vault';
}

export function parseScopeKey(key: string): GlossaryScope {
	if (key.startsWith('note:')) return { note: key.slice(5) };
	if (key.startsWith('tag:')) return { tag: key.slice(4) };
	if (key.startsWith('folder:')) return { folder: key.slice(7) };
	if (key.startsWith('property:')) {
		const rest = key.slice(9);
		const eq = rest.indexOf('=');
		return eq > 0 ? { property: { key: rest.slice(0, eq), value: rest.slice(eq + 1) } } : {};
	}
	return {};
}

/** Identity of an entry: adding the same term in the same scope updates instead of duplicating. */
export function entryKey(entry: Pick<GlossaryEntry, 'kind' | 'src' | 'target' | 'scope'>): string {
	return [entry.kind, entry.src.normalize('NFC').toLowerCase(), entry.target, scopeKey(entry.scope)].join('\u0000');
}

/** Removes characters that could break the prompt format and caps the length. */
export function cleanText(value: string, max: number): string {
	return value
		.replace(/<<\d+>>|⟦\d+⟧/g, ' ')
		.replace(/[⟦⟧`\r\n\t]/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
		.slice(0, max);
}

export function newEntryId(random: () => number = Math.random): string {
	let id = 'g';
	for (let i = 0; i < 7; i++) id += Math.floor(random() * 16).toString(16);
	return id;
}

export function serializeGlossary(file: GlossaryFile): string {
	const entries = Object.entries(file.entries).map(([id, entry]) => `\t\t${JSON.stringify(id)}: ${JSON.stringify(entry)}`);
	const domains = Object.entries(file.domains).map(([key, domain]) => `\t\t${JSON.stringify(key)}: ${JSON.stringify(domain)}`);
	const block = (lines: string[]) => (lines.length > 0 ? `\n${lines.join(',\n')}\n\t` : '');
	return `${GLOSSARY_WARNING}\n\n{\n\t"version": ${file.version},\n\t"entries": {${block(entries)}},\n\t"domains": {${block(domains)}}\n}\n`;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function sanitizeScope(value: unknown): GlossaryScope {
	if (!isRecord(value)) return {};
	if (typeof value.note === 'string' && value.note) return { note: value.note };
	if (isRecord(value.property) && typeof value.property.key === 'string' && typeof value.property.value === 'string') {
		return { property: { key: value.property.key, value: value.property.value } };
	}
	if (typeof value.tag === 'string' && value.tag) return { tag: value.tag.replace(/^#/, '') };
	if (typeof value.folder === 'string' && value.folder) return { folder: value.folder.replace(/\/+$/, '') };
	return {};
}

function sanitizeEntry(value: unknown): GlossaryEntry | null {
	if (!isRecord(value)) return null;
	const updatedAt = typeof value.updatedAt === 'string' ? value.updatedAt : new Date(0).toISOString();
	if (value.deleted === true) {
		return { kind: 'keep', src: '', target: '*', scope: {}, updatedAt, deleted: true };
	}
	const kind = value.kind;
	if (kind !== 'map' && kind !== 'avoid' && kind !== 'keep') return null;
	if (typeof value.src !== 'string' || value.src.trim().length === 0) return null;
	const target = isTargetLanguage(value.target) ? value.target : '*';
	const entry: GlossaryEntry = { kind, src: cleanText(value.src, MAX_SRC), target, scope: sanitizeScope(value.scope), updatedAt };
	if (kind === 'map') {
		if (typeof value.to !== 'string' || value.to.trim().length === 0) return null;
		entry.to = cleanText(value.to, MAX_TO);
	}
	if (kind === 'avoid') {
		const avoid = Array.isArray(value.avoid) ? value.avoid.filter((a): a is string => typeof a === 'string').map((a) => cleanText(a, MAX_TO)).filter((a) => a.length > 0) : [];
		if (avoid.length === 0) return null;
		entry.avoid = avoid.slice(0, 8);
	}
	if (typeof value.hint === 'string' && value.hint.trim()) entry.hint = cleanText(value.hint, MAX_HINT);
	if (value.match === 'stem' || value.match === 'word') entry.match = value.match;
	return entry;
}

/** Parses the glossary note. Never throws: unreadable content yields an empty glossary. */
export function parseGlossary(content: string): GlossaryFile {
	const start = content.indexOf('{');
	if (start === -1) return emptyGlossary();
	let raw: unknown;
	try {
		raw = JSON.parse(content.slice(start));
	} catch {
		return emptyGlossary();
	}
	const file = emptyGlossary();
	if (!isRecord(raw)) return file;
	if (isRecord(raw.entries)) {
		for (const [id, value] of Object.entries(raw.entries)) {
			const entry = sanitizeEntry(value);
			if (entry && /^g[0-9a-f]{7}$/.test(id)) file.entries[id] = entry;
		}
	}
	if (isRecord(raw.domains)) {
		for (const [key, value] of Object.entries(raw.domains)) {
			if (isRecord(value) && typeof value.text === 'string') {
				file.domains[key] = { text: cleanText(value.text, MAX_DOMAIN), updatedAt: typeof value.updatedAt === 'string' ? value.updatedAt : new Date(0).toISOString() };
			}
		}
	}
	return file;
}

function timeOf(updatedAt: string): number {
	const at = Date.parse(updatedAt);
	return Number.isFinite(at) ? at : 0;
}

/** Union of two glossaries (sync): per id and per domain the newer `updatedAt` wins; tombstones stay. */
export function mergeGlossary(local: GlossaryFile, remote: GlossaryFile): GlossaryFile {
	const merged = emptyGlossary();
	for (const id of new Set([...Object.keys(local.entries), ...Object.keys(remote.entries)])) {
		const a = local.entries[id];
		const b = remote.entries[id];
		merged.entries[id] = a && b ? (timeOf(a.updatedAt) >= timeOf(b.updatedAt) ? a : b) : (a ?? b)!;
	}
	for (const key of new Set([...Object.keys(local.domains), ...Object.keys(remote.domains)])) {
		const a = local.domains[key];
		const b = remote.domains[key];
		merged.domains[key] = a && b ? (timeOf(a.updatedAt) >= timeOf(b.updatedAt) ? a : b) : (a ?? b)!;
	}
	return merged;
}

/** Drops tombstones older than 90 days. Returns how many were removed. */
export function purgeTombstones(file: GlossaryFile, now: Date): number {
	const cutoff = now.getTime() - TOMBSTONE_DAYS * 24 * 60 * 60 * 1000;
	let removed = 0;
	for (const [id, entry] of Object.entries(file.entries)) {
		if (entry.deleted && timeOf(entry.updatedAt) < cutoff) {
			delete file.entries[id];
			removed++;
		}
	}
	return removed;
}

/** Rewrites note and folder scopes after a rename or move. Returns true if anything changed. */
export function rewriteScopePaths(file: GlossaryFile, from: string, to: string, now: string): boolean {
	let changed = false;
	const rewrite = (scope: GlossaryScope): GlossaryScope | null => {
		if (scope.note && (scope.note === from || scope.note.startsWith(`${from}/`))) return { note: to + scope.note.slice(from.length) };
		if (scope.folder && (scope.folder === from || scope.folder.startsWith(`${from}/`))) return { folder: to + scope.folder.slice(from.length) };
		return null;
	};
	for (const entry of Object.values(file.entries)) {
		if (entry.deleted) continue;
		const next = rewrite(entry.scope);
		if (next) {
			entry.scope = next;
			entry.updatedAt = now;
			changed = true;
		}
	}
	for (const [key, domain] of Object.entries(file.domains)) {
		const next = rewrite(parseScopeKey(key));
		if (next) {
			delete file.domains[key];
			file.domains[scopeKey(next)] = { text: domain.text, updatedAt: now };
			changed = true;
		}
	}
	return changed;
}
